import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:n + 2]]
    inner = list(range(1, n))
    count = 0
    for mask in range(1 << len(inner)):
        path = [0]
        for b in range(len(inner)):
            if mask >> b & 1:
                path.append(inner[b])
        path.append(n)
        ok = True
        for k in range(len(path)):
            if a[path[k]] == 1:
                ok = False
                break
            if k > 0 and path[k] - path[k - 1] > 3:
                ok = False
                break
        if ok:
            count += 1
    print(count % 1000000007)


main()
